<script setup>
import {computed,onMounted,ref} from 'vue';import {ElMessage,ElMessageBox} from 'element-plus';import {api} from '../bridge/jcefBridge';import PageShell from '../components/common/PageShell.vue';import ListEditor from '../components/common/ListEditor.vue';
const data=ref({agents:[],providers:[],prompts:[],skills:[],tools:[],pluginFunctionGroups:[]}),form=ref({}),sections=ref(['model']),toolQuery=ref(''),pluginQuery=ref(''),skillQuery=ref('');const filteredTools=computed(()=>data.value.tools.filter(x=>x.toLowerCase().includes(toolQuery.value.toLowerCase())));const filteredSkills=computed(()=>data.value.skills.filter(x=>x.toLowerCase().includes(skillQuery.value.toLowerCase())));const visiblePluginGroups=computed(()=>data.value.pluginFunctionGroups.map(g=>({...g,functions:g.functions.filter(f=>`${f.name} ${f.description}`.toLowerCase().includes(pluginQuery.value.toLowerCase()))})).filter(g=>g.functions.length));const models=computed(()=>data.value.providers.find(x=>x.id===form.value.providerId)?.models||[]);const agents=computed(()=>data.value.agents.filter(x=>x.id!==form.value.id));const resourceKinds=[['image','图片'],['audio','音频'],['video','视频'],['file','文件']];const personas=[['memory','memoryMaxChars','专业记忆'],['behaviorHabits','behaviorHabitsMaxChars','工作方法'],['soul','soulMaxChars','角色设定'],['profile','profileMaxChars','能力画像'],['guardrails','guardrailsMaxChars','边界约束']];function pluginGroupCount(g){return g.functions.filter(f=>form.value.pluginFunctions.includes(f.key)).length}function selectPluginGroup(g){form.value.pluginFunctions=[...new Set([...form.value.pluginFunctions,...g.functions.map(f=>f.key)])]}function clearPluginGroup(g){const keys=new Set(g.functions.map(f=>f.key));form.value.pluginFunctions=form.value.pluginFunctions.filter(x=>!keys.has(x))}function selectVisiblePlugins(){form.value.pluginFunctions=[...new Set([...form.value.pluginFunctions,...visiblePluginGroups.value.flatMap(g=>g.functions.map(f=>f.key))])]}function clearVisiblePlugins(){const keys=new Set(visiblePluginGroups.value.flatMap(g=>g.functions.map(f=>f.key)));form.value.pluginFunctions=form.value.pluginFunctions.filter(x=>!keys.has(x))}
const distillTypes=['direct_run','chat_turn','workflow_node','scheduled_run','multimodal_analysis','agent_distillation','environment_distillation'];
function fresh(){return{id:null,name:'New Agent',description:'',enabled:true,providerId:null,modelId:null,promptId:null,extraPrompt:'',outputMode:'text',maxRuntimeSecs:null,tags:[],includeHistory:false,maxHistoryMessages:null,toolCallRetentionRounds:null,tools:[...data.value.tools],toolsIncludeNew:false,pluginFunctions:[],pluginFunctionsIncludeNew:false,skills:[],skillsIncludeNew:false,skillPromptEnabled:false,viewResources:Object.fromEntries(resourceKinds.map(([k])=>[k,{enabled:false,agentId:null}])),persona:{memory:'',memoryMaxChars:512,behaviorHabits:'',behaviorHabitsMaxChars:512,soul:'',soulMaxChars:512,profile:'',profileMaxChars:512,guardrails:'',guardrailsMaxChars:512},distill:{enabled:false,agentId:null,minMessages:10,messageTypes:['chat_turn'],extraPrompt:''}}}
function normalize(x){const base=fresh();return{...base,...x,tools:x.tools||[],pluginFunctions:x.pluginFunctions||[],skills:x.skills||[],viewResources:{...base.viewResources,...(x.viewResources||{})},persona:{...base.persona,...(x.persona||{})},distill:{...base.distill,...(x.distill||{})}}}
async function load(selectId=form.value.id){data.value=await api('agents.catalog');form.value=normalize(data.value.agents.find(x=>x.id===selectId)||data.value.agents[0]||fresh())}
function saveError(error){return error?.message||String(error)||'未知错误'}
async function save(){
  try{
    await api('agent.save',form.value)
    ElMessage.success('Agent 已保存')
    await load()
  }catch(error){
    ElMessage.error({message:`Agent 保存失败：${saveError(error)}`,duration:8000,showClose:true})
  }
}
async function remove(){await ElMessageBox.confirm(`确定删除 ${form.value.name}？`,'删除 Agent',{type:'warning'});await api('agent.delete',{id:form.value.id});ElMessage.success('已删除');load(null)}onMounted(load)
</script>
<template><PageShell title="Agent 管理"><div class="management-split agent-layout"><ListEditor :items="data.agents" :selected="form.id" @select="x=>form=normalize(x)" @create="form=fresh()"/><el-scrollbar class="agent-scroll"><div class="agent-summary"><div><h3>{{form.name||'新建 Agent'}}</h3><p>{{form.description||'配置模型、资源能力、人格与蒸馏策略'}}</p></div><div><el-button v-if="form.id" type="danger" plain @click="remove">删除</el-button><el-button type="primary" @click="save">保存 Agent</el-button></div></div><el-collapse v-model="sections" class="config-collapse agent-collapse"><el-collapse-item name="model"><template #title><span class="collapse-title">模型与运行参数</span></template><el-form label-position="top" class="section-form"><div class="form-three"><el-form-item label="名称"><el-input v-model="form.name"/></el-form-item><el-form-item label="供应商"><el-select v-model="form.providerId" filterable @change="form.modelId=null"><el-option v-for="x in data.providers" :key="x.id" :label="x.name" :value="x.id"/></el-select></el-form-item><el-form-item label="模型"><el-select v-model="form.modelId" filterable><el-option v-for="x in models" :key="x.id" :label="x.name" :value="x.id"/></el-select></el-form-item><el-form-item label="提示词"><el-select v-model="form.promptId" clearable filterable><el-option v-for="x in data.prompts" :key="x.id" :label="x.name" :value="x.id"/></el-select></el-form-item><el-form-item label="输出模式"><el-select v-model="form.outputMode"><el-option label="纯文本" value="text"/><el-option label="JSON" value="json"/><el-option label="Markdown" value="markdown"/><el-option label="结构化数据" value="structured"/></el-select></el-form-item><el-form-item label="最大运行秒数"><el-input-number v-model="form.maxRuntimeSecs" :min="1"/></el-form-item><el-form-item label="标签"><el-select v-model="form.tags" multiple allow-create filterable/></el-form-item><el-form-item label="启用 Agent"><el-switch v-model="form.enabled"/></el-form-item><el-form-item label="包含历史"><el-switch v-model="form.includeHistory"/></el-form-item><el-form-item label="最大历史对话轮数"><el-input-number v-model="form.maxHistoryMessages" :min="1" clearable placeholder="不限制"/></el-form-item><el-form-item label="保留最新工具调用轮次"><el-input-number v-model="form.toolCallRetentionRounds" :min="0" clearable placeholder="不限制"/></el-form-item></div><el-form-item label="描述"><el-input v-model="form.description" type="textarea" :rows="2"/></el-form-item><el-form-item label="扩展提示"><el-input v-model="form.extraPrompt" type="textarea" :rows="3" maxlength="512" show-word-limit/></el-form-item></el-form></el-collapse-item><el-collapse-item name="resources"><template #title><span class="collapse-title">工具、插件函数与 Skills</span></template><div class="resource-policy"><section class="resource-panel"><div class="resource-title"><div><strong>内置工具</strong><small>Agent 可以直接调用的系统工具</small></div><el-checkbox v-model="form.toolsIncludeNew">包含新增</el-checkbox></div><el-input v-model="toolQuery" clearable placeholder="搜索工具"/><el-checkbox-group v-model="form.tools" class="option-grid compact-options"><el-checkbox v-for="x in filteredTools" :key="x" :value="x"><span class="option-copy"><strong>{{x}}</strong></span></el-checkbox></el-checkbox-group></section><section class="resource-panel"><div class="resource-title"><div><strong>插件函数</strong><small>由已安装插件提供的 Function Calling</small></div><el-checkbox v-model="form.pluginFunctionsIncludeNew">包含新增</el-checkbox></div><div class="plugin-toolbar"><el-input v-model="pluginQuery" clearable placeholder="搜索函数名称或描述"/><el-button size="small" @click="selectVisiblePlugins">全选当前结果</el-button><el-button size="small" @click="clearVisiblePlugins">取消当前结果</el-button></div><el-collapse class="plugin-groups"><el-collapse-item v-for="g in visiblePluginGroups" :key="g.pluginKey" :name="g.pluginKey"><template #title><div class="plugin-group-head"><span class="plugin-title">{{g.pluginName}} <small>{{pluginGroupCount(g)}} / {{g.functions.length}}</small></span><span><el-button size="small" link @click.stop="selectPluginGroup(g)">全选</el-button><el-button size="small" link @click.stop="clearPluginGroup(g)">取消全选</el-button></span></div></template><el-checkbox-group v-model="form.pluginFunctions" class="option-grid plugin-options"><el-checkbox v-for="f in g.functions" :key="f.key" :value="f.key"><span class="option-copy"><strong>{{f.name}}</strong><small>{{f.description}}</small></span></el-checkbox></el-checkbox-group></el-collapse-item></el-collapse></section><section class="resource-panel"><div class="resource-title"><div><strong>Skills</strong><small>按需向上下文注入技能说明</small></div><span><el-checkbox v-model="form.skillsIncludeNew">包含新增</el-checkbox><el-checkbox v-model="form.skillPromptEnabled">注入技能提示</el-checkbox></span></div><el-input v-model="skillQuery" clearable placeholder="搜索 Skill"/><el-checkbox-group v-model="form.skills" class="option-grid compact-options"><el-checkbox v-for="x in filteredSkills" :key="x" :value="x"><span class="option-copy"><strong>{{x}}</strong></span></el-checkbox></el-checkbox-group></section></div></el-collapse-item><el-collapse-item name="multimodal"><template #title><span class="collapse-title">多模态资源处理</span></template><div class="resource-grid"><div v-for="([key,label]) in resourceKinds" :key="key" class="resource-row"><el-checkbox v-model="form.viewResources[key].enabled">{{label}}</el-checkbox><el-select v-model="form.viewResources[key].agentId" clearable :disabled="!form.viewResources[key].enabled" placeholder="选择处理 Agent"><el-option v-for="x in agents" :key="x.id" :label="x.name" :value="x.id"/></el-select></div></div></el-collapse-item><el-collapse-item name="persona"><template #title><span class="collapse-title">角色与人格</span></template><div class="persona-grid"><article v-for="([key,maxKey,label]) in personas" :key="key" class="persona-card"><header><strong>{{label}}</strong><el-input-number v-model="form.persona[maxKey]" :min="0" size="small"/></header><el-input v-model="form.persona[key]" type="textarea" :rows="4"/></article></div></el-collapse-item><el-collapse-item name="distill" class="distill-section"><template #title><span class="collapse-title">蒸馏配置</span></template><el-form label-position="top" class="section-form"><div class="form-three"><el-form-item label="启用蒸馏"><el-switch v-model="form.distill.enabled"/></el-form-item><el-form-item label="蒸馏 Agent"><el-select v-model="form.distill.agentId" clearable><el-option v-for="x in data.agents" :key="x.id" :label="x.name" :value="x.id"/></el-select></el-form-item><el-form-item label="最小消息数"><el-input-number v-model="form.distill.minMessages" :min="1"/></el-form-item></div><el-form-item label="消息类型"><el-checkbox-group v-model="form.distill.messageTypes" class="option-grid compact-options"><el-checkbox v-for="x in distillTypes" :key="x" :value="x">{{{'direct_run':'直接运行','chat_turn':'聊天对话','workflow_node':'工作流节点','scheduled_run':'定时运行','multimodal_analysis':'多模态分析','agent_distillation':'Agent 蒸馏','environment_distillation':'环境蒸馏'}[x]}}</el-checkbox></el-checkbox-group></el-form-item><el-form-item label="额外提示"><el-input v-model="form.distill.extraPrompt" type="textarea" :rows="3"/></el-form-item></el-form></el-collapse-item></el-collapse></el-scrollbar></div></PageShell></template>
